alter table public.maq_exam_sessions add column if not exists subject text not null default 'termicas';
alter table public.maq_attempts add column if not exists subject text not null default 'termicas';
create index if not exists maq_attempt_subject_user on public.maq_attempts(user_id,subject,created_at);
create index if not exists maq_session_subject_user on public.maq_exam_sessions(user_id,subject,finished_at);
create table if not exists public.maq_question_catalog(id text primary key,subject text not null,topic integer not null,question text not null);
alter table public.maq_question_catalog enable row level security;
revoke all on public.maq_question_catalog from anon,authenticated;
grant all on public.maq_question_catalog to service_role;
on conflict(id) do update set subject=excluded.subject,topic=excluded.topic,question=excluded.question;
create or replace function public.maq_get_subject_progress(p_user_id uuid,p_subject text) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
with catalog as(select * from public.maq_question_catalog where subject=p_subject),
mine as(select * from public.maq_attempts where user_id=p_user_id and subject=p_subject),
q as(select question_id,topic,count(*)::int attempts,round(avg(score),2) average,round(max(score),2) best,round(100.0*count(*) filter(where correct)/count(*),1) accuracy,max(created_at) last_attempt from mine group by question_id,topic),
total as(select count(*)::numeric n from catalog),
tc as(select topic,count(*)::numeric n from catalog group by topic),
t as(select q.topic,sum(q.attempts)::int attempts,round(sum(q.best)/(tc.n*10)*100,2) mastery from q join tc on tc.topic=q.topic group by q.topic,tc.n),
ts as(select topic,count(*)::int attempts,round(avg(score),2) average,round(100.0*count(*) filter(where correct)/count(*),1) accuracy from mine group by topic)
select jsonb_build_object(
'subject',p_subject,'attempts',(select count(*) from mine),
'average',coalesce((select round(avg(score),2) from mine),0),
'accuracy',coalesce((select round(100.0*count(*) filter(where correct)/nullif(count(*),0),1) from mine),0),
'mastery',coalesce((select round(sum(best)/(nullif((select n from total),0)*10)*100,2) from q),0),
'practicedQuestions',(select count(*) from q),'totalQuestions',(select n from total),
'questions',coalesce((select jsonb_agg(to_jsonb(q) order by topic,question_id) from q),'[]'::jsonb),
 'topics',coalesce((select jsonb_agg(to_jsonb(ts)||jsonb_build_object('mastery',t.mastery) order by ts.topic) from ts join t using(topic)),'[]'::jsonb));
$$;
revoke all on function public.maq_get_subject_progress(uuid,text) from public,anon,authenticated;
grant execute on function public.maq_get_subject_progress(uuid,text) to service_role;
create or replace function public.maq_get_progress(p_user_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$ select public.maq_get_subject_progress(p_user_id,'termicas'); $$;
notify pgrst,'reload schema';
select subject,count(*) as preguntas from public.maq_question_catalog group by subject order by subject;
